"""Build portable, offline HTML viewers from measured MATLAB/Simulink results."""
from pathlib import Path
import csv, json, html
ROOT=Path(__file__).resolve().parents[1]
def rows(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
from presentation import page

b=ROOT; summary=json.loads((b/'results/summary.json').read_text()); data=rows(b/'results/test_predictions.csv'); stress=rows(b/'results/gain_stress.csv')
content='''<header><div class="eyebrow">PROYECTO 01 / MATLAB / MANTENIMIENTO INDUSTRIAL</div><h1>Bearing Watch</h1><p class="intro">Del acelerómetro a una decisión explicable. Detector de anomalías calibrado con registros sanos, evaluación separada por carga y alarmas con persistencia.</p><span class="badge">Datos reales CWRU · Evaluación local reproducida</span></header>
<section class="grid"><div class="card"><div class="muted">Ventanas de prueba</div><div class="metric">206</div><small>Cuatro registros · 3 hp · un banco de ensayos</small></div><div class="card"><div class="muted">Sensibilidad al umbral elegido</div><div class="metric" id="sensitivity"></div><small id="tp"></small></div><div class="card"><div class="muted">Tasa de falsas alarmas</div><div class="metric" id="falseRate"></div><small id="fp"></small></div></section>
<section class="card"><h2>Explora el compromiso de detección</h2><div class="controls"><label for="threshold">Umbral de score</label><input id="threshold" type="range" min="0" max="35" value="3" step="0.1"><output id="thresholdValue"></output><button id="reset">Restaurar benchmark</button></div><svg id="chart" viewBox="0 0 1000 340" role="img" aria-label="Score de cada ventana y umbral de detección"></svg><small>Ventanas agrupadas por registro, no una línea temporal continua. Índigo: sano; ocre: defecto. El deslizador es exploratorio: no modifica el detector ni los resultados guardados.</small></section>
<div class="flex"><section class="card"><h2>Una limitación que importa</h2><p>Un cambio de ganancia del sensor desplaza el RMS. El sistema necesita una calibración consistente con la adquisición.</p><div class="scroll"><table><thead><tr><th>Ganancia</th><th>Sensibilidad</th><th>Falsas alarmas</th></tr></thead><tbody>'''+''.join(f'<tr><td>{float(r["AcquisitionGain"]):g}×</td><td>{float(r["Sensitivity"]):.1%}</td><td>{float(r["FalseAlarmRate"]):.1%}</td></tr>' for r in stress)+'''</tbody></table></div></section><section class="card"><h2>Qué revisar en el código</h2><p>Canal exacto por archivo, separación de entrenamiento y prueba, rechazo de sensores planos y una regresión que evita cargar datos del archivo 98 al calibrar con el 99.</p><p><a href="../README.md">README</a> · <a href="../results/summary.json">Métricas JSON</a> · <a href="defensa-es.md">Guía de entrevista</a></p></section></div><p class="note">El resultado del benchmark no implica fiabilidad en planta. Los defectos fueron inducidos en laboratorio; las ventanas están correlacionadas. No se estima vida útil ni se acciona una parada de máquina.</p>'''
script='const D='+json.dumps(data,separators=(',',':'))+''';const base=3;const input=document.getElementById('threshold');function update(){const th=+input.value;let tp=0,fp=0,n=0,p=0;D.forEach(d=>{let actual=d.Label!=='healthy',flag=+d.Score>th;if(actual){p++;tp+=flag}else{n++;fp+=flag}});document.getElementById('sensitivity').textContent=(100*tp/p).toFixed(1)+' %';document.getElementById('falseRate').textContent=(100*fp/n).toFixed(1)+' %';document.getElementById('tp').textContent=tp+' / '+p+' ventanas con defecto detectadas';document.getElementById('fp').textContent=fp+' / '+n+' ventanas sanas señaladas';document.getElementById('thresholdValue').textContent=th.toFixed(1);let s='';for(let y=0;y<=35;y+=5){let py=290-y*7.2;s+='<line x1="55" y1="'+py+'" x2="970" y2="'+py+'" stroke="#e3e8ee"/><text x="20" y="'+(py+5)+'" font-size="13" fill="#61718a">'+y+'</text>'}D.forEach((d,i)=>{s+='<circle cx="'+(55+i*915/(D.length-1))+'" cy="'+(290-(+d.Score)*7.2)+'" r="3.5" fill="'+(d.Label==='healthy'?'#665efd':'#9b6829')+'"><title>'+d.Label+' / score '+(+d.Score).toFixed(2)+'</title></circle>'});const y=290-th*7.2;s+='<line x1="55" y1="'+y+'" x2="970" y2="'+y+'" stroke="#ea2261" stroke-width="2" stroke-dasharray="7 5"/><text x="55" y="325" font-size="13" fill="#61718a">Sano → pista interior → bola → pista exterior</text>';document.getElementById('chart').innerHTML=s}input.addEventListener('input',update);document.getElementById('reset').onclick=()=>{input.value=base;update()};update();'''
(b/'docs/demo.html').write_text(page('Bearing Watch — demo',content,script),encoding='utf-8')


print("Offline viewer generated from results.")

(ROOT/"docs/index.html").write_text((ROOT/"docs/demo.html").read_text(encoding="utf-8"),encoding="utf-8")
